  cSize = 32
  cAlign = 8
  pokeCStruct p x = do
    liftIO (pokeByteOff p 0 (1000396005 :: Int32))
    liftIO (pokeByteOff p 8 (nullPtr :: Ptr ()))
    liftIO (pokeByteOff p 16 (if x.micromap then TRUE else FALSE))
    liftIO (pokeByteOff p 20 (if x.micromapCaptureReplay then TRUE else FALSE))
    liftIO (pokeByteOff p 24 (if x.micromapHostCommands then TRUE else FALSE))
