  => Device
  -> MicromapCreateInfoEXT
  -> Maybe AllocationCallbacks
  -> m (Outcome MicromapEXT)
createMicromapEXT device createInfo allocator =
  liftIO $ withArena \arena_ -> runAlloc arena_ do
    p_createInfo :: Ptr () <- castPtr <$> new createInfo
    p_allocator :: Ptr () <- maybe (pure nullPtr) (fmap castPtr . new) allocator
    p_o_micromap <- arenaBytes 8 8
    r_ <-
      liftIO
        ( mkCreateMicromapEXT
            (checkCommandPtr "vkCreateMicromapEXT" device.cmds.pCreateMicromapEXT)
            (castPtr device.handle)
            p_createInfo
            p_allocator
            (castPtr p_o_micromap)
        )
    if r_ < 0 then
      pure (Err (openFromWire r_))
    else do
      w_o_micromap <- liftIO (peekByteOff p_o_micromap 0 :: IO Word64)
      let o_micromap = MicromapEXT w_o_micromap
      pure (Ok (openFromWire r_) o_micromap)

withMicromapEXT
  :: forall m r
   . (MonadUnliftIO m)
  => Device
  -> MicromapCreateInfoEXT
  -> Maybe AllocationCallbacks
  -> (Outcome MicromapEXT -> m r)
  -> m r
withMicromapEXT device createInfo allocator cont_ =
  withRunInIO \run_ ->
    bracket
      (run_ (createMicromapEXT device createInfo allocator))
      ( \o_ -> case o_ of
          Ok _ h_ -> run_ (destroyMicromapEXT device h_ allocator)
          Err _ -> pure ()
      )
      (run_ . cont_)

